<span style="font-size:11px;color:#888;margin-left:auto;">SÉANCE &nbsp;|&nbsp; 11 AOÛT 2026</span>
</div>
<div style="padding:12px 14px 8px;">
<script>(function(){
var _cs = document.currentScript;
var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");

function el(tag, attrs, txt){
  var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}

var margin = {left:110, right:24, top:18, bottom:46};
var PW = 680 - margin.left - margin.right;
var PH = 300 - margin.top - margin.bottom;

var labels = ["Air Canada","Brookfield AM","Cenovus","Suncor","Secteur industriel","Secteur de l’énergie","Canadian Natural","Imperial Oil"];
var data = [5.9, 4.6, 0.9, 0.9, 0.8, 0.8, 0.7, 0.5];
var n = data.length;

var xMax = 7;
var xp = function(v){ return margin.left + (v/xMax) * PW; };

var gap = 5;
var barH = Math.floor((PH - (n-1)*gap) / n);

var rowY = function(i){ return margin.top + i*(barH+gap); };

// 1. gridlines (vertical, since this is a horizontal bar chart)
[0,1,2,3,4,5,6,7].forEach(function(gv){
  var gx = xp(gv);
  svg.appendChild(el("line",{x1:gx, x2:gx, y1:margin.top, y2:margin.top+PH, stroke:"#ececec","stroke-width":0.5}));
});

// row labels (end-anchored, per horizontal bar convention)
for (var i=0;i<n;i++){
  svg.appendChild(el("text",{x:margin.left-4, y:rowY(i)+barH/2+3, "text-anchor":"end", "font-size":8, fill:"#999999", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, labels[i]));
}

var pillIndex = 0;

// 3. series bars
for (var i=0;i<n;i++){
  var w = xp(data[i]) - margin.left;
  var color = i < 2 ? "#3a7a55" : "#4a5568";
  svg.appendChild(el("rect",{x:margin.left, y:rowY(i), width:w, height:barH, fill:color}));
}

// 4. axis line
svg.appendChild(el("line",{x1:margin.left, x2:margin.left, y1:margin.top, y2:margin.top+PH, stroke:"#d8d8d8","stroke-width":1}));

// x-axis tick labels (bottom)
[0,2,4,6].forEach(function(gv){
  svg.appendChild(el("text",{x:xp(gv), y:margin.top+PH+16, "text-anchor":"middle", "font-size":8, fill:"#999999", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "+"+gv+"\u00a0%"));
});

// 5. bar-end value labels (suppress at pillIndex, anti-duplication)
for (var i=0;i<n;i++){
  if (i === pillIndex) continue;
  var lx = xp(data[i]) + 6;
  var ly = rowY(i) + barH/2 + 3;
  svg.appendChild(el("text",{x:lx, y:ly, "text-anchor":"start", "font-size":7.5, fill:"#444444", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "+"+data[i].toFixed(1).replace(".", ",")+"\u00a0%"));
}

// 6. gold pill on top mover (bar tip)
var pv = data[pillIndex];
var pillText = "+" + pv.toFixed(1).replace(".", ",") + "\u00a0%";
var pillW = pillText.length * 9 * 0.58 + 10;
var pillH = 16;
var barTipX = xp(pv);
var pillX = barTipX + 6;
var pillY = rowY(pillIndex) + barH/2 - pillH/2;
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+4, "text-anchor":"middle", "font-size":9, "font-weight":700, fill:"#111111", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, pillText));

_cs.parentNode.appendChild(svg);
})();
</script>
